WITH enriched AS (SELECT *, LEAD(amount) OVER (PARTITION BY merchant ORDER BY txn_time, id) next_amount, LAG(amount) OVER (PARTITION BY merchant ORDER BY txn_time, id) prev_amount, ROW_NUMBER() OVER (PARTITION BY merchant ORDER BY txn_time, id) seq_no, COUNT(amount) OVER (PARTITION BY txn_type, merchant ORDER BY CAST(txn_time AS BIGINT) RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW) amount_count_90d FROM transactions WHERE is_flagged), base AS (SELECT id, account_id, amount, txn_time, is_flagged, next_amount, seq_no, amount_count_90d, CAST(txn_time AS DATE) txn_time_day, amount_count_90d + seq_no amount_count_90d_plus_seq_no, COALESCE(merchant, 'UNKNOWN') resolved_merchant FROM enriched WHERE txn_time >= DATE '2023-04-25' AND merchant IS NOT NULL), metrics AS (SELECT *, DENSE_RANK() OVER (PARTITION BY account_id ORDER BY next_amount NULLS FIRST) next_amount_dense_rank, AVG(amount_count_90d) OVER (ORDER BY next_amount, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) amount_count_90d_avg_5, NTILE(3) OVER (ORDER BY seq_no DESC, id) seq_no_bucket FROM base), remaining_keys AS (SELECT id, account_id FROM metrics EXCEPT SELECT id, account_id FROM transactions WHERE account_id = 7), verified AS (SELECT s.* FROM metrics s INNER JOIN remaining_keys k ON s.id = k.id AND s.account_id = k.account_id) SELECT id, amount, txn_time, is_flagged, next_amount, seq_no, amount_count_90d, txn_time_day, amount_count_90d_plus_seq_no FROM verified ORDER BY id DESC, seq_no
